/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 0 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { height: var(--control-sm); padding: 0 12px; font-size: var(--text-xs); }
.btn-lg { height: var(--control-lg); padding: 0 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { height: auto; padding-block: var(--s2); }
.btn-block { width: 100%; }

/* Tour: a spotlight cut out of a dim overlay, plus a card. Positions are set in px by the component. */
.tour { position: fixed; inset: 0; z-index: var(--z-toast); pointer-events: none; }
.tour-overlay { position: fixed; inset: 0; pointer-events: auto; }
.tour-spotlight { position: fixed; box-shadow: 0 0 0 100vmax color-mix(in srgb, var(--foreground) 55%, transparent); border: 1px solid var(--background); outline: 2px solid var(--accent); pointer-events: none; }
.tour-overlay:only-child { background: color-mix(in srgb, var(--foreground) 55%, transparent); }
.tour-spotlight + .tour-card { z-index: 1; }
.tour-card { position: fixed; z-index: 1; display: grid; gap: var(--s2); width: min(22rem, calc(100vw - var(--s4) * 2)); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); pointer-events: auto; }
.tour-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.tour-count { margin: 0; font-size: var(--text-xs); color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }
.tour-title { margin: 0; font-size: var(--text-base); font-weight: 500; }
.tour-content { font-size: var(--text-sm); color: var(--muted); }
.tour-actions { display: flex; align-items: center; gap: var(--s2); margin-block-start: var(--s2); }
.tour-spacer { flex: 1; }
@media (prefers-reduced-motion: no-preference) {
  .tour-spotlight { transition: top var(--fast) var(--ease), left var(--fast) var(--ease), width var(--fast) var(--ease), height var(--fast) var(--ease); }
  .tour-card { transition: top var(--fast) var(--ease), left var(--fast) var(--ease); }
}

